mapper.select:
SELECT stock.id, stock.spare_parts_code, parts.name as spare_parts_name, stock.storeroom_code, storeroom.name as storeroom_name, stock.location_code, location.name as location_name, stock.inventory_num, parts.unit FROM tpm_spare_parts_stock as stock INNER JOIN (SELECT code, name, unit FROM tpm_spare_parts WHERE del_flag = '0') as parts ON stock.spare_parts_code = parts.code INNER JOIN (SELECT code, name FROM tpm_spare_parts_storeroom WHERE del_flag = '0') as storeroom ON stock.storeroom_code = storeroom.code INNER JOIN (SELECT code, name FROM tpm_spare_parts_location WHERE del_flag = '0') as location ON stock.location_code = location.code WHERE stock.inventory_num >0
and stock.id in
#{item}
